function fieldsSection(o,n,main=false){let s=`\n### ${n} ${o.displayName}\n\n**Internal name:** \`${o.internalName}\`. **Inheritance parent:** ${typeof o.inheritanceParent==='object'?'`'+o.inheritanceParent.name+'`':o.inheritanceParent}. **Configuration:** ${o.disposition}.\n`;
 s+=`\n**Object ID:** ${o.recordId||'Unassigned — proposed '+(o.internalName==='Shared_OperationalResource'?'external interface':'local catalogue')}${o.evidenceId?' ('+o.evidenceId+')':''}. **Abstract:** ${o.metadata.IsAbstract}. **Workflow:** ${o.metadata.HasWorkflow??false}. **Location bound:** ${o.metadata.IsLocationBound??'Unresolved'}. **Security:** ${o.metadata.IsSecurityEnabled??'Unresolved'} (preserve except §8 rules).\n`;
 if(o.targetParameters)s+=table(['Object parameter','Target value'],Object.entries(o.targetParameters));
 if(o.recordId){const refs=['DefaultDetailView','DefaultInventoryView','DisplayProperty','OrderProperty','Module'].map(k=>{const x=target(o.evidenceId,k);return [k,x?`${x.item.FieldData.Name||x.item.FieldData.Caption||x.item.Caption}; ${x.item.RecordId}`:'No binding exported; preserve native configuration'];});s+=table(['Existing object binding','Native record / instruction'],refs);}
 s+='\n**Directly declared fields:** '+(o.fields.length?o.fields.map(f=>'`'+f.internalName+'`').join(', '):'None; declarations remain on the inheritance base')+'.\n';
 if(typeof o.inheritanceParent==='object')s+='\nInherited fields are configured once on the named inheritance base. Effective subtype conditions in shared rows apply only to the named Inspection consumer.\n';
 if(o.internalName==='Shared_OperationalResource')s+='\nG05 supplies this interface; it is not a local object-creation instruction. Physical identity, inheritance and field names remain unresolved.\n';
 if(o.fields.length)s+=table(fHeads,o.fields.map(f=>[f.displayName,f.typeContract,f.required,f.defaultContract,f.editContract,`${f.lifecycleContract}${f.publication?'; publication: '+f.publication:''}. **${f.disposition}**; internal \`${f.internalName}\`${f.evidenceId?'; '+f.evidenceId:'; '+(f.proposalId||'external interface')}${f.ruleIds?.length?'; '+f.ruleIds.join(', '):''}`]));
 if(o.seedRecords?.length){const keys=[...new Set(o.seedRecords.flatMap(r=>Object.keys(r.values)))];s+='\nInitial values:\n\nInherited columns are record values, not duplicate declarations. Proposed seeds have no invented record GUID.\n';s+=table(['Basis',...keys],o.seedRecords.map(r=>[r.classification,...keys.map(k=>r.values[k]??'NULL')]));}return s;}
function inventory(os){return table(['Object / internal name','Object ID / basis','Inheritance parent','Instruction','Direct fields'],os.map(o=>[`${o.displayName} / ${o.internalName}`,o.recordId||'Proposed; no GUID',typeof o.inheritanceParent==='object'?o.inheritanceParent.name:o.inheritanceParent,o.disposition,o.fields.length]));}
