for(const [g,os]of Object.entries(groups)){const refs=[];for(const o of os)for(const f of o.fields)if(f.relationshipTarget){const key=f.relation?.$id||f.proposalId||o.internalName+'.'+f.internalName;const all=objects.flatMap(x=>x.fields);if(f.metadata?.IsStartOfRelation===false&&all.some(x=>x.relation?.$id===f.relation?.$id&&x.metadata?.IsStartOfRelation))continue;if(drawn.has(key))continue;drawn.add(key);refs.push({o,f});}const nodes=new Set(os);for(const o of os)if(typeof o.inheritanceParent==='object')nodes.add(object(o.inheritanceParent.name));for(const {f}of refs)nodes.add(object(f.relationshipTarget));diagram+='\n## '+(src.get(g)?.item.FieldData.Caption||g)+'\n\n```mermaid\nclassDiagram\ndirection LR\n';for(const o of nodes){diagram+=`class ${sid(o.internalName)}["${o.displayName.replace(/"/g,"'")}"]\n`;for(const f of o.fields.filter(f=>['IsNegative','ContributesToOutcome','ExternalInspectionReport'].includes(f.internalName)))diagram+=`${sid(o.internalName)} : +${f.internalName==='ExternalInspectionReport'?'File':'YesNo'} ${f.internalName}\n`;if(o.metadata.IsAbstract)diagram+=`<<abstract>> ${sid(o.internalName)}\n`;}for(const o of os)if(typeof o.inheritanceParent==='object')diagram+=`${sid(o.inheritanceParent.name)} <|-- ${sid(o.internalName)} : inherits\n`;for(const {o,f}of refs){if(f.cardinality==='M:N'){const mid='Map_'+sid(f.relation?.$id||f.proposalId||f.internalName);diagram+=`class ${mid}["${f.relation?.Name?.match(/via ([^)]+)/)?.[1]||o.internalName+'_'+f.internalName+'_native_map'}"]\n<<native_map>> ${mid}\n${sid(o.internalName)} --> ${mid} : ${f.internalName}\n${mid} --> ${sid(f.relationshipTarget)} : M_to_N\n`;}else diagram+=`${sid(o.internalName)} --> ${f.cardinality==='M:1'&&f.required==='Y'?'"1" ':''}${sid(f.relationshipTarget)} : ${f.internalName}${f.cardinality==='1:M'?'_inverse_1_to_M':''}\n`;associations++;}diagram+='```\n';}
